func TestGateway_ContextPropagation_ClientDisconnect(t *testing.T) {
	mock := newMockNATSRequester()

	disconnectDetected := false
	mock.requestFunc = func(ctx context.Context, subject string, data []byte, timeout time.Duration) ([]byte, error) {
		// Simulate slow processing
		select {
		case <-ctx.Done():
			disconnectDetected = true
			return nil, ctx.Err()
		case <-time.After(200 * time.Millisecond):
			return []byte(`{"result":"ok"}`), nil
		}
	}

	comp := createTestGatewayWithMock(t, mock)
	require.NoError(t, comp.Initialize())
	require.NoError(t, comp.Start(context.Background()))
	defer comp.Stop(5 * time.Second)

	gqlRequest := map[string]interface{}{
		"query": `query { pathSearch(startEntity: "acme.ops.test.graph.entity.001", maxDepth: 10) { entities } }`,
	}
	body, err := json.Marshal(gqlRequest)
	require.NoError(t, err)

	req := httptest.NewRequest(http.MethodPost, "/graphql", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")

	// Simulate client disconnect by cancelling context
	ctx, cancel := context.WithCancel(req.Context())
	req = req.WithContext(ctx)

	// Cancel immediately to simulate disconnect
	cancel()

	w := httptest.NewRecorder()

	comp.handleGraphQL(w, req)

	// Verify that context cancellation was detected
	time.Sleep(50 * time.Millisecond) // Allow goroutine to process
	assert.True(t, disconnectDetected, "should detect client disconnect")
}

